const strategyGrid=document.getElementById('strategy-grid');
strategyGrid.innerHTML=strategies.map((s,i)=>`<button class="strategy-card reveal" data-strategy="${i}" aria-haspopup="dialog"><span class="card-top">${icon(s.icon)}<span class="strategy-number">${String(i+1).padStart(2,'0')}</span></span><h3>${s.name}</h3><p>${s.thai}</p><span class="card-arrow" aria-hidden="true">↗</span></button>`).join('');
const dialog=document.getElementById('strategy-dialog');
strategyGrid.addEventListener('click',e=>{const button=e.target.closest('[data-strategy]');if(!button)return;const i=Number(button.dataset.strategy),s=strategies[i];document.getElementById('dialog-content').innerHTML=`<div class="dialog-icon">${icon(s.icon)}</div><span class="eyebrow dark">STRATEGY ${String(i+1).padStart(2,'0')} / 08</span><h2 id="dialog-title">${s.name}</h2><p>${s.detail}</p><ul>${s.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><a class="inline-link" href="#journey">เชื่อมสู่เส้นทางการเรียนรู้ <span>↗</span></a><p class="dialog-note">ชื่อกลยุทธ์อ้างอิงแผนโครงการ Canva · แนวทางข้างต้นเรียบเรียงเพื่อประกอบการเรียนรู้ ให้ใช้หลักเกณฑ์ทางการในการประเมิน</p>`;dialog.showModal();});
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('click',e=>{if(e.target.closest('a'))dialog.close();});
