const tablist=document.getElementById('journey-tabs');
tablist.innerHTML=weeks.map((w,i)=>`<button class="week-tab" id="week-tab-${i}" role="tab" aria-controls="journey-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-week="${i}"><small>WEEK</small><strong>${String(i+1).padStart(2,'0')}</strong><span>${w.month}</span></button>`).join('');
function selectWeek(i,focus=false){const w=weeks[i];tablist.querySelectorAll('[role=tab]').forEach((t,n)=>{t.setAttribute('aria-selected',String(n===i));t.tabIndex=n===i?0:-1;if(n===i&&focus)t.focus();});const panel=document.getElementById('journey-panel');panel.setAttribute('aria-labelledby',`week-tab-${i}`);panel.innerHTML=`<div><p class="panel-label">WEEK ${String(i+1).padStart(2,'0')} · ${w.month}</p><h3>${w.name}</h3><p class="panel-description">${w.subtitle}<br><br>${w.description}</p></div><div><ul class="panel-tasks">${w.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><a class="panel-link" href="#library" data-jump-filter="${w.doc}">เปิดเอกสารที่เกี่ยวข้อง <span>↗</span></a></div>`;}
selectWeek(0);
tablist.addEventListener('click',e=>{const b=e.target.closest('[data-week]');if(b)selectWeek(Number(b.dataset.week));});
tablist.addEventListener('keydown',e=>{const b=e.target.closest('[data-week]');if(!b)return;let n=Number(b.dataset.week);if(e.key==='ArrowRight')n=(n+1)%6;else if(e.key==='ArrowLeft')n=(n+5)%6;else if(e.key==='Home')n=0;else if(e.key==='End')n=5;else return;e.preventDefault();selectWeek(n,true);});
