const checks=[['เข้าใจหลักเกณฑ์ GECC 2570','อ่านเกณฑ์และทบทวนแบบประเมินความพร้อม'],['ประเมินตนเองและวิเคราะห์ช่องว่าง','รวบรวมประเด็นที่หน่วยงานต้องพัฒนา'],['จัดเก็บและสรุปผลแบบสำรวจ','ความพึงพอใจ ความต้องการ และความเชื่อมั่น'],['ปรับปรุงคำตอบและพัฒนาพื้นที่บริการ','ตรวจความสอดคล้องของคำตอบกับการดำเนินงานจริง'],['ทบทวนกับทีมพี่เลี้ยง','บันทึกข้อเสนอแนะและปรับปรุงข้อมูล'],['ตรวจเอกสารก่อนส่งสมัคร','ให้พี่เลี้ยงตรวจแบบฟอร์มและติดตามประกาศทางการ']];
let checked=[];let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem('gecc-readiness-v1')||'[]');if(Array.isArray(saved))checked=saved.filter(n=>Number.isInteger(n)&&n>=0&&n<checks.length);}catch{storageAvailable=false;}
const checklist=document.getElementById('checklist');
checklist.innerHTML=checks.map((c,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${checked.includes(i)?'checked':''}><span><strong>${c[0]}</strong><small>${c[1]}</small></span></label>`).join('');
function updateProgress(){const n=checklist.querySelectorAll('input:checked').length,p=Math.round(n/checks.length*100);document.getElementById('progress-ring').style.setProperty('--progress',`${p}%`);document.getElementById('progress-percent').textContent=`${p}%`;document.getElementById('progress-count').textContent=n?`เตรียมแล้ว ${n} จาก ${checks.length} รายการ`:'เริ่มต้นเตรียมความพร้อม';}
function saveProgress(){checked=Array.from(checklist.querySelectorAll('input:checked')).map(x=>Number(x.dataset.check));try{localStorage.setItem('gecc-readiness-v1',JSON.stringify(checked));storageAvailable=true;document.getElementById('storage-note').textContent='บันทึกความพร้อมในเบราว์เซอร์นี้แล้ว';}catch{storageAvailable=false;document.getElementById('storage-note').textContent='เบราว์เซอร์ไม่อนุญาตให้บันทึก รายการนี้จะอยู่เฉพาะระหว่างเปิดหน้าเว็บ';}updateProgress();}
checklist.addEventListener('change',saveProgress);updateProgress();
if(!storageAvailable)document.getElementById('storage-note').textContent='ไม่สามารถอ่านข้อมูลที่บันทึกไว้ได้ คุณยังใช้รายการในหน้านี้ได้';
