let activeFilter='all';const search=document.getElementById('document-search');
function renderDocuments(){const query=search.value.trim().toLocaleLowerCase('th');const matches=documents.filter(d=>(activeFilter==='all'||d.category===activeFilter)&&`${d.title} ${d.description} ${d.type}`.toLocaleLowerCase('th').includes(query));document.getElementById('results-count').textContent=`แสดง ${matches.length} จาก ${documents.length} รายการ`;document.getElementById('document-grid').innerHTML=matches.length?matches.map(d=>`<a class="document-card" href="${d.url}" target="_blank" rel="noopener noreferrer"><div class="doc-top"><span class="doc-icon">${icon(d.type==='CANVA'?'spark':'file')}</span><span class="doc-type">${d.type}</span></div><h3>${d.title}</h3><p>${d.description}</p><div class="doc-bottom"><span>เปิดเอกสาร${d.url.startsWith('assets')?'ฉบับเต็ม':'ต้นฉบับ'}</span><span aria-hidden="true">↗</span></div></a>`).join(''):'<p class="empty-results">ไม่พบเอกสารที่ค้นหา ลองใช้คำอื่นหรือเลือกหมวด “ทั้งหมด”</p>';}
function setFilter(value){activeFilter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const isActive=b.dataset.filter===value;b.classList.toggle('active',isActive);b.setAttribute('aria-pressed',String(isActive));});renderDocuments();}
document.querySelector('.filter-group').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b)setFilter(b.dataset.filter);});search.addEventListener('input',renderDocuments);renderDocuments();
document.getElementById('journey-panel').addEventListener('click',e=>{const link=e.target.closest('[data-jump-filter]');if(link){search.value='';setFilter(link.dataset.jumpFilter);}});
const menuButton=document.querySelector('.menu-button'),navigation=document.getElementById('navigation');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','เปิดเมนู');navigation.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'ปิดเมนู':'เปิดเมนู');navigation.classList.toggle('open',open);});navigation.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});window.addEventListener('resize',()=>{if(window.innerWidth>850)closeMenu();});
let toastTimer;function showToast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2800);}
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let motionPaused=reducedMotion.matches;
function setMotion(){document.documentElement.classList.toggle('motion-paused',motionPaused);const b=document.getElementById('motion-toggle');b.setAttribute('aria-pressed',String(motionPaused));b.innerHTML=`${icon(motionPaused?'play':'pause')} ${motionPaused?'เปิดโมชั่น':'หยุดโมชั่น'}`;}
setMotion();document.getElementById('motion-toggle').addEventListener('click',()=>{motionPaused=!motionPaused;setMotion();});reducedMotion.addEventListener('change',e=>{motionPaused=e.matches;setMotion();});
if('IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
let ticking=false;window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const height=document.documentElement.scrollHeight-window.innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${height>0?window.scrollY/height:0})`;ticking=false;});ticking=true;}},{passive:true});
